import{_ as p,r as s,o,c,e as n,a as l,s as d}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Ресайзер - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Изменение размера файла на диске","slug":"изменение-размера-фаила-на-диске","link":"#изменение-размера-фаила-на-диске","children":[{"level":3,"title":"Параметры изменения размера","slug":"параметры-изменения-размера","link":"#параметры-изменения-размера","children":[]},{"level":3,"title":"Доступные режимы","slug":"доступные-режимы","link":"#доступные-режимы","children":[]}]},{"level":2,"title":"Изменение размера файла для браузера","slug":"изменение-размера-фаила-для-браузера","link":"#изменение-размера-фаила-для-браузера","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/extend/services/resizer.md","filePath":"3.x/ru/extend/services/resizer.md"}'),i={name:"3.x/ru/extend/services/resizer.md"};function r(u,a,k,h,g,m){const e=s("pre-heading"),t=s("post-heading");return o(),c("div",null,[n(e),a[0]||(a[0]=l("h1",null,"Ресайзер",-1)),n(t),a[1]||(a[1]=d(`<h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>October CMS поставляется с ресайзером изображений, который позволяет изменять форму и размер поддерживаемых изображений.</p><h2 id="изменение-размера-фаила-на-диске"><a href="#изменение-размера-фаила-на-диске" class="header-anchor">#</a> Изменение размера файла на диске</h2><p>Для изменения размера изображения используйте метод <code>open</code> фасада <code>Resizer</code>, указав путь к файлу.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name static-context">Resizer</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/image.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете передать загруженный файл из <a href="./request-input.html">ввода запроса страницы</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name static-context">Resizer</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;field_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для изменения размера изображения вызовите метод <code>resize</code> на объекте. Первый аргумент — ширина изображения, второй — высота изображения, а третий — массив параметров изменения размера.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Аргументы ширины и высоты также необязательны. Например, чтобы использовать существующую ширину и изменить только высоту, передайте второй аргумент как <code>null</code>. Это значение затем вычисляется с использованием исходного соотношения сторон изображения (автоматическое пропорциональное масштабирование) на основе опции <code>mode</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token constant">null</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Наконец, используйте метод <code>save</code> для сохранения изменённого изображения в новом расположении.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/new/file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="параметры-изменения-размера"><a href="#параметры-изменения-размера" class="header-anchor">#</a> Параметры изменения размера</h3><p>В массиве опций поддерживаются следующие элементы:</p><div class="table"><table tabindex="0"><thead><tr><th>Ключ</th><th>Описание</th><th>По умолчанию</th><th>Варианты</th></tr></thead><tbody><tr><td><code>mode</code></td><td>Как изображение должно быть подогнано под размеры</td><td><code>auto</code></td><td><code>exact</code>, <code>portrait</code>, <code>landscape</code>, <code>auto</code>, <code>fit</code> или <code>crop</code></td></tr><tr><td><code>offset</code></td><td>Смещение обрезки изменённого изображения</td><td><code>[0,0]</code></td><td>[left, top]</td></tr><tr><td><code>quality</code></td><td>Качество изменённого изображения</td><td><code>90</code></td><td><code>0-100</code></td></tr><tr><td><code>sharpen</code></td><td>Степень резкости изображения</td><td><code>0</code></td><td><code>0-100</code></td></tr></tbody></table></div><h3 id="доступные-режимы"><a href="#доступные-режимы" class="header-anchor">#</a> Доступные режимы</h3><p>Опция <code>mode</code> позволяет указать, как изображение должно быть изменено. Доступные режимы следующие:</p><div class="table"><table tabindex="0"><thead><tr><th>Режим</th><th>Описание</th></tr></thead><tbody><tr><td><code>auto</code></td><td>Автоматический выбор между <code>portrait</code> и <code>landscape</code> на основе ориентации изображения</td></tr><tr><td><code>exact</code></td><td>Изменить размер до точных указанных размеров без сохранения соотношения сторон</td></tr><tr><td><code>portrait</code></td><td>Изменить размер до указанной высоты и адаптировать ширину для сохранения соотношения сторон</td></tr><tr><td><code>landscape</code></td><td>Изменить размер до указанной ширины и адаптировать высоту для сохранения соотношения сторон</td></tr><tr><td><code>crop</code></td><td>Обрезать до указанных размеров после максимального вписывания изображения в эти размеры</td></tr><tr><td><code>fit</code></td><td>Вписать изображение в указанные максимальные размеры, сохраняя соотношение сторон</td></tr></tbody></table></div><h2 id="изменение-размера-фаила-для-браузера"><a href="#изменение-размера-фаила-для-браузера" class="header-anchor">#</a> Изменение размера файла для браузера</h2><p>Класс <code>System\\Classes\\ResizeImages</code> может использоваться для изменения размера изображения и предоставления его через URL:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$url</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token variable">$image</span><span class="token punctuation">,</span> <span class="token variable">$width</span><span class="token punctuation">,</span> <span class="token variable">$height</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы изменяете размер элемента из медиабиблиотеки, вам следует разрешить путь к медиа с помощью класса <code>Media\\Classes\\MediaLibrary</code> и метода <code>url</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Media<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>MediaLibrary</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;relative/path/to/asset.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$url</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token variable">$image</span><span class="token punctuation">,</span> <span class="token variable">$width</span><span class="token punctuation">,</span> <span class="token variable">$height</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Также существует фильтр разметки <code>|resize</code>, который можно использовать для <a href="./../../markup/filter/resize.html">изменения размера изображений в ваших темах</a>.</p></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../../markup/filter/resize.html">Фильтр Resize</a></li><li><a href="./../../markup/filter/media.html">Фильтр Media</a></li></ul></div>`,27))])}const b=p(i,[["render",r]]);export{f as __pageData,b as default};
